  if (input.model) {
    cliArgs.push('--model', input.model);
  }
  cliArgs.push('--dangerously-skip-permissions');
  const effort = input.agentOptions?.effort;
  if (effort) {
    cliArgs.push('--effort', String(effort));
  }
  cliArgs.push(input.prompt);
  return cliArgs;
}

