import React from 'react';
import {Card, Flex, Loader, SegmentedRadioGroup, Text} from '@gravity-ui/uikit';
import {ChartKit} from './chartkit';
import {toMonitoringWidgetData, toSalesWidgetData} from './adapters';
import type {VizWidgetMode, VizWidgetProps} from './types';

const MODE_OPTIONS = [
  {value: 'sales', content: 'Продажи'},
  {value: 'monitoring', content: 'Мониторинг'},
];

export function VizWidget({title, data, mode, defaultMode = 'sales', onModeChange, height = 320}: VizWidgetProps) {
  const [innerMode, setInnerMode] = React.useState<VizWidgetMode>(defaultMode);
  const activeMode = mode ?? innerMode;

  const handleUpdate = (value: string) => {
    const next = value as VizWidgetMode;
    setInnerMode(next);
    onModeChange?.(next);
  };

  const widgetData = React.useMemo(
    () => activeMode === 'sales' ? toSalesWidgetData(data.sales) : toMonitoringWidgetData(data.monitoring),
    [activeMode, data],
  );

  return (
    <Card view="raised" size="l" ...>
      <Flex direction="column" gap={4} ...>
        <Flex alignItems="center" gap={3}>
          <Text variant="subheader-2" style={{flex: 1, minWidth: 0}}>{title}</Text>
          <SegmentedRadioGroup size="m" value={activeMode} options={MODE_OPTIONS} onUpdate={handleUpdate} style={{flexShrink: 0}} name="viz-mode" />
        </Flex>
        <div style={{height}}>
          <ChartKit
            key={activeMode}
            type={activeMode === 'sales' ? 'gravity-charts' : 'yagr'}
            data={widgetData as never}
            renderPluginLoader={() => (
              <Flex alignItems="center" justifyContent="center" style={{height: '100%'}}>
                <Loader size="m" />
              </Flex>
            )}
          />
        </div>
      </Flex>
    </Card>
  );
